import org.junit.jupiter.api.Disabled;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

@DisplayName("100/96_minimum_genetic_mutation (incomplete)")
class SolutionIncompleteTest {

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldReturnOneForSingleMutation() {

        Solution solution = new Solution();

        assertEquals(
            1,
            solution.minMutation("AACCGGTT", "AACCGGTA", new String[]{"AACCGGTA"})
        );
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldReturnTwoForShortestPath() {

        Solution solution = new Solution();

        assertEquals(
            2,
            solution.minMutation(
                "AACCGGTT",
                "AAACGGTA",
                new String[]{"AACCGGTA", "AACCGCTA", "AAACGGTA"}
            )
        );
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldReturnThreeForLongerPath() {

        Solution solution = new Solution();

        assertEquals(
            3,
            solution.minMutation(
                "AAAAACCC",
                "AACCCCCC",
                new String[]{"AAAACCCC", "AAACCCCC", "AACCCCCC"}
            )
        );
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldReturnNegativeOneWhenEndMissingFromBank() {

        Solution solution = new Solution();

        assertEquals(
            -1,
            solution.minMutation("AACCGGTT", "AACCGGTA", new String[]{})
        );
    }
}

